 insert into contributions(id,scholar_id,description,title,kind,confidence,discipline_id,period_text,prior_state,detail,label) values ('aac8d9ce-93b0-5bc5-a73f-9b0152c2e245',sid,'A treatise answering a published prediction of a planetary alignment, recalculating planetary positions on a geocentric model and arguing from gravitation against the predicted effects (as described in S1).','Critique of the 1919 planetary-alignment prediction (Mu''in-i-Mubin)','commentary_or_synthesis','medium',did,'1919','A prediction by Albert F. Porta, based on heliocentric astronomy (per S1).','A written response with its own geocentric calculation. Whether the calculation is sound has not been examined.','under_review');
